
/**
 * Represents a simulated execution action (Buy or Sell) generated by a trading strategy.
 * <p>
 * The {@code Trade} class acts as a domain entity holding execution details
 * such as the target asset ticker, the execution price, and the order
 * direction. It provides formatting logic to log trade transactions to the
 * standard output.
 * </p>
 *
 * @author [Your Name]
 * @version 1.0
 */
public class Trade {

    private final String ticker;
    private final double executionPrice;
    private final boolean isBuy;

    /**
     * Constructs a new Trade execution record.
     *
     * @param ticker The financial symbol of the asset being traded (e.g.,
     * "AAPL")
     * @param executionPrice The price at which the order was executed
     * @param isBuy {@code true} if the order is a buy/long execution;
     * {@code false} if it is a sell/short execution
     */
    public Trade(String ticker, double executionPrice, boolean isBuy) {
        this.ticker = ticker;
        this.executionPrice = executionPrice;
        this.isBuy = isBuy;
    }

    /**
     * Formats and prints the details of the executed trade to the console.
     * <p>
     * Translates the boolean order direction into clear text ("BOUGHT" or
     * "SOLD") alongside the ticker symbol and execution price.
     * </p>
     */
    public void printTradeDetails() {
        String action = isBuy ? "BOUGHT" : "SOLD";
        System.out.println("Trade Executed: " + action + " " + ticker + " @ $" + executionPrice);
    }
}
